@Test(dependsOnMethods = "testRebalance")
public void testAlgorithmException() throws IOException, HelixRebalanceException {
    _metadataStore.reset();
    WagedRebalancer rebalancer = new WagedRebalancer(_metadataStore, _algorithm, Optional.empty());
    ResourceControllerDataProvider clusterData = setupClusterDataCache();
    Map<String, Resource> resourceMap = clusterData.getIdealStates().entrySet().stream().collect(Collectors.toMap(entry -> entry.getKey(), entry -> {
        Resource resource = new Resource(entry.getKey());
        entry.getValue().getPartitionSet().stream().forEach(partition -> resource.addPartition(partition));
        return resource;
    }));
    // Rebalance with normal configuration. So the assignment will be persisted in the metadata store.
    Map<String, IdealState> result = rebalancer.computeNewIdealStates(clusterData, resourceMap, new CurrentStateOutput());
    // Recreate a rebalance with the same metadata store but bad algorithm instance.
    RebalanceAlgorithm badAlgorithm = Mockito.mock(RebalanceAlgorithm.class);
    when(badAlgorithm.calculate(any())).thenThrow(new HelixRebalanceException("Algorithm fails.", HelixRebalanceException.Type.FAILED_TO_CALCULATE));
    rebalancer = new WagedRebalancer(_metadataStore, badAlgorithm, Optional.empty());
    // Calculation will fail
    try {
        rebalancer.computeBestPossibleAssignment(clusterData, resourceMap, clusterData.getEnabledLiveInstances(), new CurrentStateOutput(), badAlgorithm);
        Assert.fail("Rebalance shall fail.");
    } catch (HelixRebalanceException ex) {
        Assert.assertEquals(ex.getFailureType(), HelixRebalanceException.Type.FAILED_TO_CALCULATE);
        Assert.assertEquals(ex.getMessage(), "Algorithm fails. Failure Type: FAILED_TO_CALCULATE");
    }
    // But if call with the public method computeNewIdealStates(), the rebalance will return with
    // the previous rebalance result.
    Map<String, IdealState> newResult = rebalancer.computeNewIdealStates(clusterData, resourceMap, new CurrentStateOutput());
    Assert.assertEquals(newResult, result);
    // Ensure failure has been recorded
    Assert.assertEquals(rebalancer.getMetricCollector().getMetric(WagedRebalancerMetricCollector.WagedRebalancerMetricNames.RebalanceFailureCounter.name(), CountMetric.class).getValue().longValue(), 1l);
}

