    }));
    CardDealingAdjustmentAlgorithmV2Accessor algorithm = new CardDealingAdjustmentAlgorithmV2Accessor(_topology, DEFAULT_REPLICA_COUNT, CardDealingAdjustmentAlgorithmV2.Mode.EVENNESS);
